/**
 * Fallback manager handles graceful degradation strategies
 */
export class FallbackManager {
    constructor(options?: {});
    options: {
        enabled: boolean;
        defaultValue: any;
        useFallbackRules: boolean;
        onFallback: any;
    };
    fallbackRules: Map<any, any>;
    fallbackValues: Map<any, any>;
    fallbackHistory: Map<any, any>;
    /**
     * Register a fallback rule for a specific rule
     * @param {string} ruleId - Primary rule ID
     * @param {Object} fallbackRule - Alternative rule to use
     */
    registerFallbackRule(ruleId: string, fallbackRule: Object): void;
    /**
     * Register a fallback value for a specific rule
     * @param {string} ruleId
     * @param {any} value
     */
    registerFallbackValue(ruleId: string, value: any): void;
    /**
     * Execute with fallback handling
     * @param {string} ruleId
     * @param {Function} fn - Primary execution function
     * @param {Function} fallbackFn - Optional fallback execution function
     * @returns {Promise<any>}
     */
    execute(ruleId: string, fn: Function, fallbackFn?: Function): Promise<any>;
    /**
     * Record fallback usage
     * @param {string} ruleId
     * @param {Error} error
     */
    recordFallback(ruleId: string, error: Error): void;
    /**
     * Get fallback history for a rule
     * @param {string} ruleId
     * @returns {Array}
     */
    getFallbackHistory(ruleId: string): any[];
    /**
     * Clear fallback history
     * @param {string} ruleId - Optional specific rule
     */
    clearHistory(ruleId: string): void;
    /**
     * Get statistics
     * @returns {Object}
     */
    getStats(): Object;
    /**
     * Clear all registrations
     */
    clear(): void;
}
